mapper.select:
SELECT  FROM ai_host h

  AND h.host_name LIKE concat('%', #{hostName}, '%')
  AND h.ip LIKE concat('%', #{ip}, '%')
  AND h.status = #{status}
  AND h.dept_id = #{deptId}

ORDER BY h.host_id ASC

