host_name = #{hostName}, ip = #{ip}, ssh_port = #{sshPort}, ssh_protocol = #{sshProtocol}, username = #{username}, auth_type = #{authType}, password_cipher = #{passwordCipher}, private_key_cipher = #{privateKeyCipher}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = NOW()
WHERE host_id = #{hostId}

